@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class GuestCard {
  + cardNumber : int
  + date : date
}

class IdentityCard {
  + cardNumber : int
}

class Car {
  + licensePlate : string
}

class CarPark {
  + isFull : boolean
}

class Barrier {
  + isRaised : boolean
}

class CardReader {
  + verify(cardNumber : int) : boolean
}

class Reception {
  + collectGuestCard()
  + returnGuestCard()
}

Employee "1" -- "1" IdentityCard
IdentityCard "1" -- "1" Employee

GuestCard "0..*" -- "1" Reception

CarPark "1" -- "2" Barrier
CarPark "1" -- "1" CardReader
CarPark "1" -- "1" Sign

Car "1" -- "1" Barrier : enters/leaves
Car "1" -- "1" CardReader : uses
Car "1" -- "1" IdentityCard : presents
Car "1" -- "1" GuestCard : presents

class Sign {
  + status : string
}

@enduml

